  ?zone rdfs:label ?label .
  FILTER(CONTAINS(LCASE(str(?label)), "perimeter_mid_zn_4"))
  ?sensor brick:isPartOf ?zone .
  ?sensor ref:hasTimeseriesId ?ts .
}

