  ?zone rdfs:label "Perimeter_mid_ZN_4" .
  ?sensor brick:isPartOf ?zone .
  ?sensor rdf:type ?cls .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ts . }
}

